import { test, expect } from '@playwright/test';

test.describe('Search Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should return results for a misspelled search term', async ({ page }) => {
    await page.getByRole('textbox', { name: /search/i }).fill('appl'); // Misspelled search term
    await page.getByRole('button', { name: /search/i }).click();

    const results = await page.getByRole('heading', { name: /results/i }).isVisible();
    expect(results).toBe(true);

    const firstResult = await page.getByText(/apple/i).isVisible();
    expect(firstResult).toBe(true);
  });

  test('should suggest corrections for a misspelled search term', async ({ page }) => {
    await page.getByRole('textbox', { name: /search/i }).fill('bananna'); // Misspelled search term
    await page.getByRole('button', { name: /search/i }).click();

    const suggestion = await page.getByText(/did you mean banana\?/i).isVisible();
    expect(suggestion).toBe(true);
  });
});
